import { z } from 'zod'

/**
 * Redeeming merchant offers and reporting on redemptions (feature 035).
 *
 * Any active account may redeem — a member, staff, or a merchant or partner
 * user — so a redemption names its redeemer by kind. The kinds are the
 * platform's account kinds; `admin` is what the rest of the platform calls
 * staff in the database.
 */

export const REDEEMER_KINDS = Object.freeze(['member', 'admin', 'merchant', 'partner'] as const)
export type RedeemerKind = (typeof REDEEMER_KINDS)[number]

export const redeemRequestSchema = z.object({
  /**
   * Generated by the client once per tap and reused on a retry. The server
   * answers a repeat with the original redemption, so a double tap or a retry
   * after a lost response cannot become two.
   */
  requestId: z.string().uuid(),
})

export const redemptionSchema = z.object({
  id: z.string().uuid(),
  /** What the person shows at the store. */
  reference: z.string(),
  redeemedAt: z.string(),
  offerId: z.string().uuid(),
  offerTitle: z.string(),
  merchantName: z.string().nullable(),
  /** A derivative of the offer's lead image, or null. Never an original. */
  thumbnailUrl: z.string().nullable(),
})

export const redemptionListSchema = z.object({
  items: z.array(redemptionSchema),
  nextCursor: z.string().nullable(),
})

export const redemptionQuerySchema = z.object({ cursor: z.string().optional() })

/** Report filters. `organisationId` is honoured on the platform report only. */
export const redemptionReportQuerySchema = z.object({
  offerId: z.string().uuid().optional(),
  categoryId: z.string().uuid().optional(),
  organisationId: z.string().uuid().optional(),
  from: z.string().datetime().optional(),
  to: z.string().datetime().optional(),
  cursor: z.string().optional(),
})

export const redemptionReportSchema = z.object({
  /** Over the whole filtered set, not just this page. */
  totals: z.object({
    count: z.number().int(),
    /** Null when no redemption in the set has prices to estimate from. */
    estimatedSavingCents: z.number().int().nullable(),
  }),
  byOffer: z.array(z.object({
    offerId: z.string().uuid(),
    title: z.string(),
    categoryId: z.string().uuid(),
    count: z.number().int(),
  })),
  /** Totals per day within the filtered range (the report's "per period"). */
  byDay: z.array(z.object({ day: z.string(), count: z.number().int() })),
  rows: z.array(z.object({
    id: z.string().uuid(),
    reference: z.string(),
    redeemedAt: z.string(),
    offerId: z.string().uuid(),
    offerTitle: z.string(),
    categoryId: z.string().uuid(),
    redeemerKind: z.enum(REDEEMER_KINDS),
    /**
     * A handle, "First L.", or a staff or organisation display name. Never an
     * email, a number or an id.
     */
    redeemerName: z.string(),
  })),
  nextCursor: z.string().nullable(),
})

export type RedeemRequest = z.infer<typeof redeemRequestSchema>
export type Redemption = z.infer<typeof redemptionSchema>
export type RedemptionReport = z.infer<typeof redemptionReportSchema>
export type RedemptionReportQuery = z.infer<typeof redemptionReportQuerySchema>
